package stonytark.cinemarr.server;
import net.fabricmc.fabric.api.command.v2.CommandRegistrationCallback;
import net.minecraft.commands.Commands;
import net.minecraft.network.chat.Component;
import stonytark.cinemarr.core.platform.CinemarrSettings;
public final class CinemarrCommands {public static void register(){CommandRegistrationCallback.EVENT.register((dispatcher,registries,environment)->dispatcher.register(Commands.literal("cinemarr").executes(c->status(c.getSource())).then(Commands.literal("status").executes(c->status(c.getSource()))).then(Commands.literal("diagnostics").requires(s->s.hasPermission(CinemarrSettings.operatorPermissionLevel())).executes(c->{c.getSource().sendSuccess(()->Component.literal(CinemarrServer.instance().videoDiagnostics()),false);return 1;})).then(Commands.literal("retry").requires(s->s.hasPermission(CinemarrSettings.operatorPermissionLevel())).executes(c->retry(c.getSource()))).then(CinemarrTvCommands.command())));}private static int status(net.minecraft.commands.CommandSourceStack source){source.sendSuccess(()->Component.literal(CinemarrServer.instance().videoStatus()),false);return 1;}private static int retry(net.minecraft.commands.CommandSourceStack source){boolean started=CinemarrServer.instance().retryPlex();source.sendSuccess(()->Component.literal(started?"Cinemarr Plex connection attempt started":"Cinemarr Plex is disabled or not configured"),false);return started?1:0;}private CinemarrCommands(){}}
